import{_ as t,l as s,o as e,c as n,v as r,p as l,x as i,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"后缀数组的应用","description":"","frontmatter":{"title":"后缀数组的应用","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/suffix-array-applications.md","filePath":"cs/suffix-array-applications.md","lastUpdated":1789023840000}'),h={name:"cs/suffix-array-applications.md"};function P(f,a,A,_,u,m){const o=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="后缀数组的应用" tabindex="-1">后缀数组的应用 <a class="header-anchor" href="#后缀数组的应用" aria-label="Permalink to &quot;后缀数组的应用&quot;">​</a></h1><div class="epigraph"><p>后缀排序加上 LCP，$O(1)$ 任意后缀对最长公共前缀；子串、重复、字典序区间都变成数组上的区间。</p><footer>—— 据 Manber and Myers, Suffix Arrays, 1993；Kasai 等 LCP 线性；Kärkkäinen–Sanders 线性 SA 整理</footer></div><p>上一课<a href="/cs/minimal-rotation">最小表示法</a>可用 \\(s+s\\) 的最小后缀。<a href="/cs/suffix-array">后缀数组</a>已给出构造，本课不重写倍增/SA-IS。缺口是<strong>应用</strong>：LCP、子串次数、最长重复、两个串的 LCS（拼接）。后课 Lyndon。把 <code>sa[i]</code> 当第 \\(i\\) 小后缀起点，配合 <code>rk</code>、<code>lcp</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Kasai：按名次顺序用已有 LCP 减一延长，\\(O(n)\\) 得 <code>lcp[i]=LCP(sa[i],sa[i-1])</code>。任意两后缀 LCP = <code>rk</code> 之间 <code>lcp</code> 的 RMQ。子串出现次数：对应 SA 上一段，长度用 LCP 二分或单调栈。最长重复子串：\\(\\max lcp\\)。两串最长公共子串：拼接后看相邻 SA 来自不同串的 \\(lcp\\)。</p><p>缺口是查询，不是再排序后缀。</p><h3 id="不是后缀树课" tabindex="-1">不是后缀树课 <a class="header-anchor" href="#不是后缀树课" aria-label="Permalink to &quot;不是后缀树课&quot;">​</a></h3><p>后缀树能同样做，空间与常数不同。本课数组。不要把 SAM 当 SA。</p><p><span class="marginnote">Manber–Myers 1993。Kasai LCP。后课 Lyndon 分解与 SA/Duval 接口。正则爆炸下一单元末。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构造 SA+LCP。RMQ 预处理。具体题化成 SA 区间或 LCP 直方图（单调栈矩形）。</p>',11)),(e(),l(p,null,{default:i(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SA%5B%22sa%20%2F%20rk%22%5D%20--%3E%20LCP%5B%22lcp%20%E6%95%B0%E7%BB%84%22%5D%0A%20%20LCP%20--%3E%20RMQ%5B%22%E5%90%8E%E7%BC%80%E5%AF%B9%20LCP%22%5D%0A%20%20LCP%20--%3E%20APP%5B%22%E9%87%8D%E5%A4%8D%20%2F%20%E5%87%BA%E7%8E%B0%E6%AC%A1%E6%95%B0%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>多串加不同分隔符。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后缀排序使相同前缀相邻，LCP 相邻最小，远的取区间 min。与 Z：Z 是与全串，LCP 任意对。与 KMP：单模式；SA 管所有子串。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 SA-IS 逐步证明。不写压缩后缀数组全文。后课默认：子串统计优先 SA+LCP。下一课 Lyndon 分解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SA + LCP + RMQ = 后缀 LCP 查询。</li><li>重复与出现次数在 LCP 直方图上。</li><li>构造当黑盒，本课用。</li><li>出处：Manber and Myers, 1993；Kasai 等。</li></ul>',7))])}const L=t(h,[["render",P]]);export{S as __pageData,L as default};
